"""
Mailpit Helper - 用于安全测试场景中读取 mock SMTP 邮件
使用方式：
    from mailpit_helper import get_latest_email, get_verification_code

Mailpit 需要在容器启动时运行：
    /usr/local/bin/mailpit --smtp 127.0.0.1:1025 --listen 127.0.0.1:8025 --quiet &
"""

import re
import time
import requests

MAILPIT_API = "http://127.0.0.1:8025"


def get_messages(to_email=None, limit=50):
    """获取邮件列表"""
    params = {"limit": limit}
    if to_email:
        params["query"] = f"to:{to_email}"
    resp = requests.get(f"{MAILPIT_API}/api/v1/messages", params=params)
    resp.raise_for_status()
    return resp.json().get("messages", [])


def get_message_detail(message_id):
    """获取邮件详情（含正文）"""
    resp = requests.get(f"{MAILPIT_API}/api/v1/message/{message_id}")
    resp.raise_for_status()
    return resp.json()


def get_latest_email(to_email, timeout=10):
    """等待并获取发送到指定邮箱的最新一封邮件正文"""
    deadline = time.time() + timeout
    while time.time() < deadline:
        messages = get_messages(to_email)
        if messages:
